-- ============================================================
-- Autumn Gateway Dashboard — basic_* 基础表结构（PostgreSQL）
--
-- 与 schema-basic-mysql.sql 语义一致，仅 DDL 语法适配 PostgreSQL：
--   AUTO_INCREMENT              -> BIGINT GENERATED BY DEFAULT AS IDENTITY
--   TINYINT                     -> SMALLINT
--   DATETIME / TIMESTAMP        -> TIMESTAMP
--   去掉 ENGINE / CHARSET / COLLATE / USING BTREE / 内联 COMMENT
--   唯一键 -> CONSTRAINT ... UNIQUE；普通索引 -> CREATE INDEX IF NOT EXISTS
--   注释改用 COMMENT ON TABLE / COMMENT ON COLUMN（幂等，可重复执行）
--
-- 幂等说明：CREATE TABLE IF NOT EXISTS + CREATE INDEX IF NOT EXISTS，
--          可安全重复执行，适配 spring.sql.init.mode=always 多次启动。
--
-- 注意：PostgreSQL 不支持 ON UPDATE CURRENT_TIMESTAMP，
--      update_time / updated_at 的自动更新需由应用层维护（如 MyBatis-Plus
--      @TableField(fill = FieldFill.INSERT_UPDATE)），或自行添加触发器，
--      本脚本不处理，与现有 schema-postgresql.sql 保持一致。
-- ============================================================


-- basic_app 应用（多应用隔离）
CREATE TABLE IF NOT EXISTS basic_app (
    id          BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    app_code    VARCHAR(64) NOT NULL,
    name        VARCHAR(64) NOT NULL,
    base_path   VARCHAR(128),
    description VARCHAR(255),
    status      SMALLINT DEFAULT 1,
    created_at  TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    updated_at  TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT uk_appid UNIQUE (app_code)
);
CREATE INDEX IF NOT EXISTS idx_status ON basic_app(status);

COMMENT ON TABLE basic_app IS '应用（多应用隔离）';
COMMENT ON COLUMN basic_app.app_code IS '短标识，如 order、crm、admin';
COMMENT ON COLUMN basic_app.base_path IS '该应用 API 统一前缀，如 /api/order';
COMMENT ON COLUMN basic_app.status IS '1=正常 0=禁用';


-- basic_group 用户岗位/职位/Title
CREATE TABLE IF NOT EXISTS basic_group (
    id          BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name        VARCHAR(100) NOT NULL,
    create_time TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    update_time TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    deleted     INT NOT NULL DEFAULT 0,
    code        VARCHAR(100) NOT NULL DEFAULT '',
    org_id      BIGINT NOT NULL DEFAULT 0,
    job_id      BIGINT NOT NULL DEFAULT 0
);
CREATE INDEX IF NOT EXISTS basic_user_group_name_IDX ON basic_group(name);
CREATE INDEX IF NOT EXISTS basic_group_org_id_IDX ON basic_group(org_id);

COMMENT ON TABLE basic_group IS '用户岗位/职位/Title';
COMMENT ON COLUMN basic_group.id IS 'ID';
COMMENT ON COLUMN basic_group.name IS '岗位名称，职位名称，title';
COMMENT ON COLUMN basic_group.create_time IS '创建时间';
COMMENT ON COLUMN basic_group.update_time IS '更新时间';
COMMENT ON COLUMN basic_group.deleted IS '是否删除：0-否 1-是';
COMMENT ON COLUMN basic_group.code IS '岗位编码';
COMMENT ON COLUMN basic_group.org_id IS '部门名称';
COMMENT ON COLUMN basic_group.job_id IS '岗位ID';


-- basic_menu 菜单
CREATE TABLE IF NOT EXISTS basic_menu (
    id                  BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    app_id              BIGINT NOT NULL DEFAULT 0,
    parent_id           BIGINT NOT NULL DEFAULT 0,
    menu_type           SMALLINT NOT NULL DEFAULT 0,
    menu_name           VARCHAR(50) NOT NULL DEFAULT '',
    menu_url            VARCHAR(2000) NOT NULL DEFAULT '',
    menu_identification VARCHAR(200) NOT NULL DEFAULT '',
    menu_icon           VARCHAR(100) NOT NULL DEFAULT '',
    sort_num            INT NOT NULL DEFAULT 0,
    menu_status         SMALLINT NOT NULL DEFAULT 1,
    del_flag            SMALLINT NOT NULL DEFAULT 0,
    create_user         BIGINT NOT NULL DEFAULT 0,
    create_time         TIMESTAMP NOT NULL DEFAULT '1970-01-01 00:00:00',
    update_user         BIGINT NOT NULL DEFAULT 0,
    update_time         TIMESTAMP NOT NULL DEFAULT '1970-01-01 00:00:00',
    remark              VARCHAR(200) NOT NULL DEFAULT ''
);
CREATE INDEX IF NOT EXISTS idx_menu_app_id ON basic_menu(app_id);
CREATE INDEX IF NOT EXISTS idx_menu_parent_id ON basic_menu(parent_id);

COMMENT ON TABLE basic_menu IS '菜单';
COMMENT ON COLUMN basic_menu.id IS 'ID';
COMMENT ON COLUMN basic_menu.app_id IS '应用ID，关联 basic_app.id';
COMMENT ON COLUMN basic_menu.parent_id IS '父级ID';
COMMENT ON COLUMN basic_menu.menu_type IS '权限类型：1-目录 2-菜单 3-按钮';
COMMENT ON COLUMN basic_menu.menu_name IS '菜单名称';
COMMENT ON COLUMN basic_menu.menu_url IS '接口url（多个采用英文逗号分隔）';
COMMENT ON COLUMN basic_menu.menu_identification IS '菜单或按钮标识';
COMMENT ON COLUMN basic_menu.menu_icon IS '菜单图标';
COMMENT ON COLUMN basic_menu.sort_num IS '菜单排序';
COMMENT ON COLUMN basic_menu.menu_status IS '菜单状态：1-启用 2-停用';
COMMENT ON COLUMN basic_menu.del_flag IS '是否删除：0-否 1-是';
COMMENT ON COLUMN basic_menu.create_user IS '创建人id';
COMMENT ON COLUMN basic_menu.create_time IS '创建时间';
COMMENT ON COLUMN basic_menu.update_user IS '更新人id';
COMMENT ON COLUMN basic_menu.update_time IS '更新时间';
COMMENT ON COLUMN basic_menu.remark IS '备注';


-- basic_oper_log 操作日志记录
CREATE TABLE IF NOT EXISTS basic_oper_log (
    id             BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    app_code       VARCHAR(50) NOT NULL DEFAULT '',
    business_type  VARCHAR(50) NOT NULL DEFAULT '',
    title          VARCHAR(100) NOT NULL DEFAULT '',
    request_id     VARCHAR(50) NOT NULL DEFAULT '',
    request_url    VARCHAR(200) NOT NULL DEFAULT '',
    request_method VARCHAR(100) NOT NULL DEFAULT '',
    request_data   VARCHAR(2000) NOT NULL DEFAULT '',
    class_method   VARCHAR(200) NOT NULL DEFAULT '',
    consume_time   INT NOT NULL DEFAULT 0,
    response_data  VARCHAR(2000) NOT NULL DEFAULT '',
    status         SMALLINT NOT NULL DEFAULT 0,
    error_msg      VARCHAR(2000) NOT NULL DEFAULT '',
    oper_id        BIGINT NOT NULL DEFAULT 0,
    oper_ip        VARCHAR(50) NOT NULL DEFAULT '',
    op_time        TIMESTAMP NOT NULL DEFAULT '1970-01-01 00:00:00'
);
CREATE INDEX IF NOT EXISTS idx_oper_log_op_time ON basic_oper_log(op_time);
CREATE INDEX IF NOT EXISTS idx_oper_log_oper_id ON basic_oper_log(oper_id);

COMMENT ON TABLE basic_oper_log IS '操作日志记录';
COMMENT ON COLUMN basic_oper_log.id IS 'ID';
COMMENT ON COLUMN basic_oper_log.app_code IS '系统标识';
COMMENT ON COLUMN basic_oper_log.business_type IS '业务类型';
COMMENT ON COLUMN basic_oper_log.title IS '请求标题';
COMMENT ON COLUMN basic_oper_log.request_id IS '请求ID';
COMMENT ON COLUMN basic_oper_log.request_url IS '请求URL';
COMMENT ON COLUMN basic_oper_log.request_method IS '请求方法';
COMMENT ON COLUMN basic_oper_log.request_data IS '请求数据';
COMMENT ON COLUMN basic_oper_log.class_method IS '执行方法';
COMMENT ON COLUMN basic_oper_log.consume_time IS '执行时间（毫秒）';
COMMENT ON COLUMN basic_oper_log.response_data IS '响应结果';
COMMENT ON COLUMN basic_oper_log.status IS '操作状态：0-正常 1-异常';
COMMENT ON COLUMN basic_oper_log.error_msg IS '操作错误消息';
COMMENT ON COLUMN basic_oper_log.oper_id IS '操作人';
COMMENT ON COLUMN basic_oper_log.oper_ip IS '操作人IP';
COMMENT ON COLUMN basic_oper_log.op_time IS '操作时间';


-- basic_resource 权限原子项（合并了 Resource 的 URL 四元组）
CREATE TABLE IF NOT EXISTS basic_resource (
    id          BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    app_id      BIGINT NOT NULL,
    app_code    VARCHAR(64) NOT NULL,
    name        VARCHAR(64),
    path        VARCHAR(255),
    http_method VARCHAR(16) DEFAULT 'ALL',
    match_type  VARCHAR(16) DEFAULT 'exact',
    description VARCHAR(255),
    status      SMALLINT DEFAULT 1,
    created_at  TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    updated_at  TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX IF NOT EXISTS idx_resource_app_code ON basic_resource(app_code);

COMMENT ON TABLE basic_resource IS '权限原子项（合并了 Resource 的 URL 四元组）';
COMMENT ON COLUMN basic_resource.name IS '权限名称，如"创建订单"';
COMMENT ON COLUMN basic_resource.path IS 'URL 模式，如 /api/order/:id；MENU 时为路由路径';
COMMENT ON COLUMN basic_resource.http_method IS 'ALL / GET / POST / PUT / DELETE / PATCH';
COMMENT ON COLUMN basic_resource.match_type IS 'exact / prefix / suffix';
COMMENT ON COLUMN basic_resource.status IS '1=正常 0=禁用';


-- basic_role 角色表
CREATE TABLE IF NOT EXISTS basic_role (
    id          BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    app_id      BIGINT NOT NULL DEFAULT 0,
    code        VARCHAR(50) NOT NULL DEFAULT '',
    name        VARCHAR(50) NOT NULL DEFAULT '',
    type        SMALLINT NOT NULL DEFAULT 0,
    status      SMALLINT NOT NULL DEFAULT 1,
    del_flag    SMALLINT NOT NULL DEFAULT 0,
    create_user BIGINT NOT NULL DEFAULT 0,
    create_time TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    update_user BIGINT NOT NULL DEFAULT 0,
    update_time TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    remark      VARCHAR(50) NOT NULL DEFAULT '',
    master      INT NOT NULL DEFAULT 2
);
CREATE INDEX IF NOT EXISTS idx_role_app_id ON basic_role(app_id);

COMMENT ON TABLE basic_role IS '角色表';
COMMENT ON COLUMN basic_role.id IS 'ID';
COMMENT ON COLUMN basic_role.app_id IS '应用ID，关联 basic_app.id';
COMMENT ON COLUMN basic_role.code IS '角色编码';
COMMENT ON COLUMN basic_role.name IS '角色名';
COMMENT ON COLUMN basic_role.type IS '角色类型：1-系统角色 2-自定义角色';
COMMENT ON COLUMN basic_role.status IS '状态：1-启用 2-停用';
COMMENT ON COLUMN basic_role.del_flag IS '是否删除：0-否 1-是';
COMMENT ON COLUMN basic_role.create_user IS '创建人id';
COMMENT ON COLUMN basic_role.create_time IS '创建时间';
COMMENT ON COLUMN basic_role.update_user IS '更新人id';
COMMENT ON COLUMN basic_role.update_time IS '更新时间';
COMMENT ON COLUMN basic_role.remark IS '备注';
COMMENT ON COLUMN basic_role.master IS '是否是管理员: 1-管理员；2-普通';


-- basic_role_group 用户组与角色关联表
CREATE TABLE IF NOT EXISTS basic_role_group (
    id          BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    role_id     BIGINT NOT NULL DEFAULT 0,
    group_id    BIGINT NOT NULL DEFAULT 0,
    deleted     INT NOT NULL DEFAULT 0,
    create_time TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    update_time TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    op_user_id  BIGINT NOT NULL DEFAULT 0
);
CREATE INDEX IF NOT EXISTS basic_role_group_role_id_IDX ON basic_role_group(role_id);
CREATE INDEX IF NOT EXISTS basic_role_group_group_id_IDX ON basic_role_group(group_id);

COMMENT ON TABLE basic_role_group IS '用户组与角色关联表';
COMMENT ON COLUMN basic_role_group.id IS 'ID';
COMMENT ON COLUMN basic_role_group.role_id IS '角色ID';
COMMENT ON COLUMN basic_role_group.group_id IS '用户组ID';
COMMENT ON COLUMN basic_role_group.deleted IS '删除状态：0-否 1-是';
COMMENT ON COLUMN basic_role_group.create_time IS '创建时间';
COMMENT ON COLUMN basic_role_group.update_time IS '更新时间';
COMMENT ON COLUMN basic_role_group.op_user_id IS '操作人';


-- basic_role_permission 角色权限关联表
CREATE TABLE IF NOT EXISTS basic_role_permission (
    id          BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    role_id     BIGINT NOT NULL,
    ref_id      BIGINT NOT NULL,
    create_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    update_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    del_flag    INT NOT NULL DEFAULT 0,
    op_user_id  BIGINT NOT NULL DEFAULT 0,
    type        INT NOT NULL DEFAULT 1
);
CREATE INDEX IF NOT EXISTS basic_role_permission_role_IDX ON basic_role_permission(role_id, ref_id);

COMMENT ON TABLE basic_role_permission IS '角色权限关联表';
COMMENT ON COLUMN basic_role_permission.id IS 'ID';
COMMENT ON COLUMN basic_role_permission.role_id IS '角色Id';
COMMENT ON COLUMN basic_role_permission.ref_id IS 'data_scope_id/menu_id';
COMMENT ON COLUMN basic_role_permission.create_time IS '创建时间';
COMMENT ON COLUMN basic_role_permission.update_time IS '更新时间';
COMMENT ON COLUMN basic_role_permission.del_flag IS '删除状态: 0:否，1：是';
COMMENT ON COLUMN basic_role_permission.op_user_id IS '操作人Id';
COMMENT ON COLUMN basic_role_permission.type IS '权限类型：1-菜单权限；2-资源；3-数据权限';


-- basic_user 基础用户表
CREATE TABLE IF NOT EXISTS basic_user (
    id             BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    emp_no         VARCHAR(50) NOT NULL DEFAULT '',
    admin          INT NOT NULL DEFAULT 0,
    latest_role_id BIGINT NOT NULL DEFAULT 0,
    create_time    TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    update_time    TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX IF NOT EXISTS user_emp_no_IDX ON basic_user(emp_no);

COMMENT ON TABLE basic_user IS '基础用户表';
COMMENT ON COLUMN basic_user.id IS 'ID';
COMMENT ON COLUMN basic_user.emp_no IS 'ESB人员工号';
COMMENT ON COLUMN basic_user.admin IS '是否是管理员：1-是；0：否';
COMMENT ON COLUMN basic_user.latest_role_id IS '最近登录使用角色Id';
COMMENT ON COLUMN basic_user.create_time IS '创建时间';
COMMENT ON COLUMN basic_user.update_time IS '更新时间';


-- basic_user_access_role 用户最后登录角色，解决多端登录
CREATE TABLE IF NOT EXISTS basic_user_access_role (
    id             BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    user_id        BIGINT NOT NULL DEFAULT 0,
    latest_role_id BIGINT NOT NULL DEFAULT 0,
    create_time    TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    update_time    TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    emp_no         VARCHAR(50) NOT NULL DEFAULT '',
    del_flag       INT NOT NULL DEFAULT 0,
    access_time    BIGINT NOT NULL DEFAULT 0
);
CREATE INDEX IF NOT EXISTS basic_user_jwt_role_user_id_IDX ON basic_user_access_role(user_id);
CREATE INDEX IF NOT EXISTS basic_user_jwt_role_jwt_short_IDX ON basic_user_access_role(emp_no);
CREATE INDEX IF NOT EXISTS basic_user_access_role_update_time_IDX ON basic_user_access_role(update_time);

COMMENT ON TABLE basic_user_access_role IS '用户最后登录角色，解决多端登录';
COMMENT ON COLUMN basic_user_access_role.id IS 'ID';
COMMENT ON COLUMN basic_user_access_role.user_id IS '用户Id';
COMMENT ON COLUMN basic_user_access_role.latest_role_id IS '最近登录使用角色Id';
COMMENT ON COLUMN basic_user_access_role.create_time IS '创建时间';
COMMENT ON COLUMN basic_user_access_role.update_time IS '更新时间';
COMMENT ON COLUMN basic_user_access_role.emp_no IS 'jwt头部32位，用于索引。';
COMMENT ON COLUMN basic_user_access_role.del_flag IS '删除标志：0-否，1-是';
COMMENT ON COLUMN basic_user_access_role.access_time IS '登录系统时间，就是生成jwt的create_time';


-- basic_user_group 员工岗位关联表
CREATE TABLE IF NOT EXISTS basic_user_group (
    id          BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    deleted     INT NOT NULL DEFAULT 0,
    create_time TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    update_time TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    user_id     BIGINT NOT NULL DEFAULT 0,
    group_id    BIGINT NOT NULL DEFAULT 0
);
CREATE INDEX IF NOT EXISTS idx_user_group_user_id ON basic_user_group(user_id);
CREATE INDEX IF NOT EXISTS idx_user_group_group_id ON basic_user_group(group_id);

COMMENT ON TABLE basic_user_group IS '员工岗位关联表';
COMMENT ON COLUMN basic_user_group.id IS 'ID';
COMMENT ON COLUMN basic_user_group.deleted IS '删除：0-否 1-是';
COMMENT ON COLUMN basic_user_group.create_time IS '创建时间';
COMMENT ON COLUMN basic_user_group.update_time IS '更新时间';
COMMENT ON COLUMN basic_user_group.user_id IS '用户Id';
COMMENT ON COLUMN basic_user_group.group_id IS '岗位Id';


-- basic_user_role 基础用户关联角色表
CREATE TABLE IF NOT EXISTS basic_user_role (
    id          BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    app_id      SMALLINT NOT NULL DEFAULT 0,
    eid         BIGINT NOT NULL DEFAULT 0,
    user_id     BIGINT NOT NULL DEFAULT 0,
    role_id     BIGINT NOT NULL DEFAULT 0,
    del_flag    SMALLINT NOT NULL DEFAULT 0,
    create_user BIGINT NOT NULL DEFAULT 0,
    create_time TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    update_user BIGINT NOT NULL DEFAULT 0,
    update_time TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    remark      VARCHAR(200) NOT NULL DEFAULT ''
);
CREATE INDEX IF NOT EXISTS basic_user_role_user_id_IDX ON basic_user_role(user_id);
CREATE INDEX IF NOT EXISTS basic_user_role_role_id_IDX ON basic_user_role(role_id);

COMMENT ON TABLE basic_user_role IS '基础用户关联角色表';
COMMENT ON COLUMN basic_user_role.id IS 'ID';
COMMENT ON COLUMN basic_user_role.app_id IS '应用ID：1-运营后台 2-POP后台 3-B2B后台 4-互联网医院后台 5-数据中台 6-销售助手 100-商家后台';
COMMENT ON COLUMN basic_user_role.eid IS '企业ID';
COMMENT ON COLUMN basic_user_role.user_id IS '用户ID';
COMMENT ON COLUMN basic_user_role.role_id IS '角色ID';
COMMENT ON COLUMN basic_user_role.del_flag IS '是否删除：0-否 1-是';
COMMENT ON COLUMN basic_user_role.create_user IS '创建人id';
COMMENT ON COLUMN basic_user_role.create_time IS '创建时间';
COMMENT ON COLUMN basic_user_role.update_user IS '更新人id';
COMMENT ON COLUMN basic_user_role.update_time IS '更新时间';
COMMENT ON COLUMN basic_user_role.remark IS '备注';
